import json,hashlib
from pathlib import Path
x={}
for root in ['/usr/include/c++/11','/usr/include/x86_64-linux-gnu/c++/11','/usr/lib/gcc/x86_64-linux-gnu/11/include','/usr/local/include','/usr/include/x86_64-linux-gnu','/usr/include']:
 p=Path(root); h={}
 for f in sorted(p.rglob('*')):
  if f.is_file():
   try:h[str(f)]=hashlib.sha256(f.read_bytes()).hexdigest()
   except OSError:pass
 x[root]=h
print(json.dumps(x))
